El* El::Hover(const StateStyle& s) {
    if (s.set) {
        ElStyleStates* states = EnsureStyleStates();
        StyleApplyFields(&states->hover, s.style, s.set);
        states->hoverSet |= s.set;
    }
    return this;
}

