            float x1 = hasPrevC ? (2 * cx - pcx) : cx;
            float y1 = hasPrevC ? (2 * cy - pcy) : cy;
            float c1x = cx + 2.f / 3.f * (x1 - cx);
            float c1y = cy + 2.f / 3.f * (y1 - cy);
            float c2x = x + 2.f / 3.f * (x1 - x);
            float c2y = y + 2.f / 3.f * (y1 - y);
            AddCubic(ic, c1x, c1y, c2x, c2y, x, y);
