void PaneNode::Walk(Func1<const PaneNode*> visit) const {
    if (visit.IsValid()) {
        visit.Call(this);
    }
    if (paneKind == PaneKind::Split) {
        for (int i = 0; i < children.len; i++) {
            children[i]->Walk(visit);
        }
    }
}

bool PaneNode::Empty() const {
    if (paneKind == PaneKind::Split) {
        return children.len == 0;
    }
    if (paneKind == PaneKind::Tabs) {
        return panels.len == 0;
    }
    return tiles.len == 0;
}

