static void Prefix(JsonWriter* w, const char* key) {
    if (!w->out) {
        return;
    }
    if (w->depth >= 0 && w->depth < 32 && w->wrote[w->depth]) {
        w->out->AppendChar(',');
    }
    if (w->depth >= 0 && w->depth < 32) {
        w->wrote[w->depth] = true;
    }
    if (!key) {
        return;
    }
    w->out->AppendChar('"');
    w->out->Append(Str(key));
    w->out->Append(StrL("\":"));
}

static void base_json_Push(JsonWriter* w) {
    w->depth++;
    if (w->depth < 32) {
        w->wrote[w->depth] = false;
    }
}

static void base_json_Pop(JsonWriter* w) {
    if (w->depth > 0) {
        w->depth--;
    }
}

void JsonWriter::BeginObject(const char* key) {
    Prefix(this, key);
    if (out) {
        out->AppendChar('{');
    }
    base_json_Push(this);
}
void JsonWriter::EndObject() {
    base_json_Pop(this);
    if (out) {
        out->AppendChar('}');
    }
}
void JsonWriter::BeginArray(const char* key) {
    Prefix(this, key);
    if (out) {
        out->AppendChar('[');
    }
    base_json_Push(this);
}
void JsonWriter::EndArray() {
    base_json_Pop(this);
    if (out) {
        out->AppendChar(']');
    }
}
void JsonWriter::Number(const char* key, double v) {
    Prefix(this, key);
    if (!out) {
        return;
    }

    if (v == (double)(long long)v) {
        out->Append(fmt("%lld", (long long)v));
    } else {
        out->Append(fmt("%.6g", v));
    }
}
void JsonWriter::Bool(const char* key, bool v) {
    Prefix(this, key);
    if (out) {
        out->Append(v ? StrL("true") : StrL("false"));
    }
}
void JsonWriter::String(const char* key, Str v) {
    Prefix(this, key);
    if (!out) {
        return;
    }
    out->AppendChar('"');
    for (int i = 0; i < v.len; i++) {
        char c = v.s[i];
        if (c == '"' || c == '\\') {
            out->AppendChar('\\');
            out->AppendChar(c);
        } else if (c == '\n') {
            out->Append(StrL("\\n"));
        } else if (c == '\t') {
            out->Append(StrL("\\t"));
        } else if (c == '\r') {
            out->Append(StrL("\\r"));
        } else {
            out->AppendChar(c);
        }
    }
    out->AppendChar('"');
}
void JsonWriter::Null(const char* key) {
    Prefix(this, key);
    if (out) {
        out->Append(StrL("null"));
    }
}

