void TextViewState::OnLineClamp(TextViewState* state, Ctx* cx,
                                const LineClampEvent* event) {
    if (!state || !event || state->clamped == event->clamped) {
        return;
    }
    state->clamped = event->clamped;

    Notify(cx);
}

