void TilesPaintOrder(const TilesState* s, int* out) {
    for (int i = 0; i < s->items.len; i++) {
        out[i] = i;
    }

    for (int i = 1; i < s->items.len; i++) {
        int v = out[i];
        int j = i - 1;
        while (j >= 0 && s->items[out[j]].zIndex > s->items[v].zIndex) {
            out[j + 1] = out[j];
            j--;
        }
        out[j + 1] = v;
    }
}

