static float AccordionFontPx(UiSize s) {
    switch (s) {
        case UiSize::XSmall:
            return 13;
        case UiSize::Large:
            return 16;
        default:
            return 14;
    }
}

static void AccordionPad(UiSize s, float* padY, float* padX) {
    switch (s) {
        case UiSize::XSmall:
            *padY = 4;
            *padX = 6;
            return;
        case UiSize::Small:
            *padY = 6;
            *padX = 8;
            return;
        case UiSize::Large:
            *padY = 12;
            *padX = 16;
            return;
        default:
            *padY = 8;
            *padX = 12;
            return;
    }
}

static float AccordionTitleGap(UiSize s) {
    return (s == UiSize::XSmall || s == UiSize::Small) ? 4.f : 8.f;
}

static El* AccordionRefine(El* e, const AccordionStyle& s) {
    if (s.padT >= 0) {
        e->PadT(s.padT);
    }
    if (s.padB >= 0) {
        e->PadB(s.padB);
    }
    if (s.padL >= 0) {
        e->PadL(s.padL);
    }
    if (s.padR >= 0) {
        e->PadR(s.padR);
    }
    if (s.fg.a != 0) {
        e->Fg(s.fg);
    }
    return e;
}

