El* Separator::IntoEl() {
    const Theme& th = ThemeNow(cx->app);
    Rgba c = hasColor ? color : th.border;
    El* root = Div(a)->ItemsCenter()->JustifyCenter()->Shrink0();
    if (vertical) {

        root->H(kFill);
        if (!label.s) {
            root->W(1);
        }
        El* lineEl = Div(a)->W(1)->H(kFill);
        if (label.s) {
            lineEl->Absolute();
        }

        if (line == SeparatorStyle::Dashed) {

            lineEl->Dashed()->DashArray(4, 2)->Border(1, c);
        } else {
            lineEl->Bg(c);
        }
        root->Child(lineEl);
    } else {
        root->FlexRow()->W(kFill)->H(label.s ? 24.f : 1.f);

        El* lineEl = Div(a)->H(1);
        if (label.s) {
            lineEl->Flex1()->MinW(0);
        } else {
            lineEl->W(kFill);
        }
        if (line == SeparatorStyle::Dashed) {

            lineEl->Dashed()->DashArray(4, 2)->Border(1, c);
        } else {
            lineEl->Bg(c);
        }
        root->Child(lineEl);
    }
    if (label.s) {
        root->Child(TextEl(a, label)
                        ->Font(12)
                        ->Fg(th.mutedFg)
                        ->Bg(th.tokens.background)
                        ->PadX(8));
    }
    return root;
}

