static const float kMinCellWidth = 100.f;

static TableCellEl* NewCell(Ctx* cx, bool head) {
    Arena* a = cx->a;
    TableCellEl* c = ArenaNew<TableCellEl>(a);
    c->a = a;
    c->cx = cx;
    c->head = head;
    return c;
}

