    ArenaStr at = (ArenaStr)base::ArenaOffsetOf(a, rec);
    RecSetNext(rec, n->firstStr);
    rec[kRecKind] = (char)(uint8_t)k;
    base::VarintPut(rec + kRecLen, len);
