bool IsUnicodePunctuation(uint32_t cp) {
    int lo = 0;
    int hi = (int)(sizeof(kPunctuation) / sizeof(kPunctuation[0])) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (cp < kPunctuation[mid].first) {
            hi = mid - 1;
        } else if (cp > kPunctuation[mid].last) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

