HRESULT WinAccessibilityNode::get_LargeChange(double* out) {
    if (!out) {
        return E_INVALIDARG;
    }
    const AccessibilityNode* node = Node();
    if (!node || !node->slider) {
        return UIA_E_ELEMENTNOTAVAILABLE;
    }
    double step = node->slider->step > 0
                      ? node->slider->step
                      : (node->slider->max - node->slider->min) / 100.0;
    *out = step * 10;
    return S_OK;
}

