    const AccessibilityNode* node = Node();
    if (!node) {
        return UIA_E_ELEMENTNOTAVAILABLE;
    }
    if (!AccessibilitySelectionContainerRole(node->info.role)) {
        return UIA_E_INVALIDOPERATION;
    }

    *out = FALSE;
